insert into activities (id, domain, age_band, title, why, duration_minutes, duration_label, materials, instructions, benefit, source) values
  ('book-naming-session-m7_9', 'communication'::domain, 'm7_9'::age_band, 'Book Naming Session', 'A short, repeatable activity that supports understanding first words.', 8, '5–10 min', 'Board book', 'Board book: point to each picture, name it, wait 5 seconds. ''Woh kya hai? Haan: aam! Mango. Peela aam.'' Dual-language counts.', 'Understanding runs well ahead of speaking at this age, and this builds the comprehension that first words will grow from. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('simple-instruction-practice-m7_9', 'communication'::domain, 'm7_9'::age_band, 'Simple Instruction Practice', 'A playful activity that builds pre-verbal communication (gesture).', null, 'Ongoing', 'None', 'Use consistent simple instructions with gesture: ''Come here'' + open arms. ''Give me'' + open hand. Gesture + word together.', 'Understanding runs well ahead of speaking at this age, and this builds the comprehension that first words will grow from. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('babble-conversation-record-m7_9', 'communication'::domain, 'm7_9'::age_band, 'Babble Conversation Record', 'A hands-on activity for developing babbling and sound imitation.', 8, '5–10 min', 'Phone for recording', 'Record 2 minutes of serve-and-return babble conversation. Listen back: count how many turns baby takes. Target: 3+ by 9 months.', 'This is the window where gestures and sounds start carrying meaning, which is language beginning. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'WHO Screen Time Guidelines (under 5); IAP Screen Time Guidance; IAP'),
  ('name-body-parts-m7_9', 'communication'::domain, 'm7_9'::age_band, 'Name Body Parts', 'A hands-on activity for developing understanding first words.', 8, '5–10 min', 'None', 'Staying within arm''s reach throughout, touch each body part and name it while bathing or dressing. ''Yeh naak hai. Yeh haath.'' Touch plus name = dual encoding.', 'Understanding runs well ahead of speaking at this age, and this builds the comprehension that first words will grow from. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('find-hidden-toy-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Find Hidden Toy', 'A short, repeatable activity that supports object permanence.', 7, '5–8 min', 'Cloth and toy', 'Show baby an interesting toy. While they watch, hide it under a cloth. Say ''Kahaan gayi?'' Watch whether they search under the cloth.', 'Your baby is discovering that things still exist when they cannot see them, which is one of the biggest ideas of the first year. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('cloth-get-toy-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Cloth Get Toy', 'A short, repeatable activity that supports object permanence.', 7, '5–8 min', 'Cloth and toy', 'Place a toy on a cloth, toy out of reach but cloth within reach. Watch if baby pulls the cloth to get the toy: means-ends planning.', 'Thinking at this age is entirely hands-on, built by doing rather than by being shown. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('see-what-happens-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'See What Happens', 'A hands-on activity for developing object permanence and cause-and-effect.', 8, '5–10 min', 'Any cause-effect toy', 'Any toy that produces a response when pressed or moved. Systematic testing of what each element does is emerging scientific method.', 'Your baby is discovering that things still exist when they cannot see them, which is one of the biggest ideas of the first year. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('sort-big-small-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Sort Big Small', 'A playful activity that builds object permanence and cause-and-effect.', 8, '5–10 min', 'Objects of two distinct sizes', 'Offer objects in two distinct sizes. Watch how baby handles them differently: size discrimination precedes sorting by months.', 'Your baby is discovering that things still exist when they cannot see them, which is one of the biggest ideas of the first year. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('imitation-game-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Imitation Game', 'A short, repeatable activity that supports cause-and-effect understanding.', 7, '5–8 min', 'None', 'Tap a surface, shake your head, clap: do a simple action and wait. Imitation of familiar actions appears around 8–9 months.', 'This is when babies begin to understand that their actions cause things to happen, and they test it endlessly. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('object-memory-game-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Object Memory Game', 'A hands-on activity for developing object permanence.', 7, '5–8 min', 'Two cups and small toy', 'Let baby see you hide an object under one of two cups. Which cup do they look under? Tracking invisible displacement is developing.', 'Your baby is discovering that things still exist when they cannot see them, which is one of the biggest ideas of the first year. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('someone-new-slowly-m7_9', 'social_emotional'::domain, 'm7_9'::age_band, 'Someone New, Slowly', 'A short, repeatable activity that supports recognising familiar and unfamiliar people.', 8, '5–10 min', 'None', 'When baby shows anxiety with new people, hold them securely and engage the stranger warmly. Don''t force contact: baby reads your calm.', 'Your baby now knows familiar faces from unfamiliar ones, and this helps them navigate that with you close by. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('honouring-stop-signal-m7_9', 'social_emotional'::domain, 'm7_9'::age_band, 'Honouring ''Stop'' Signal', 'A playful activity that builds attachment and early social play.', null, 'Ongoing', 'None', 'When baby clearly communicates ''no more'' (turns away, arches), stop immediately. Teaching: your communication is respected.', 'Your baby now knows familiar faces from unfamiliar ones, and this helps them navigate that with you close by. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('longer-goodbye-practice-m7_9', 'social_emotional'::domain, 'm7_9'::age_band, 'Longer Goodbye Practice', 'A playful activity that builds early separation tolerance.', 13, '10–15 min', 'None', 'Leave baby with a known caregiver for 10–15 min. Return before distress. Consistent returns build the trust that makes separations easier.', 'This supports the attachment that will let your baby explore confidently later. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('mirror-game-together-m7_9', 'social_emotional'::domain, 'm7_9'::age_band, 'Mirror Game Together', 'A hands-on activity for developing social play and reciprocity.', 7, '5–8 min', 'Large mirror', 'Sit in front of a large mirror with baby. Point to their reflection, then yours. ''Kaun hai yeh? Tum ho!'' Social-cognitive learning.', 'Social games and shared attention become possible around now, and they are how relationships start being two-way. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('favourite-laughs-list-m7_9', 'social_emotional'::domain, 'm7_9'::age_band, 'Favourite Laughs List', 'A playful activity that builds social play and reciprocity.', 8, '5–10 min', 'None', 'Find 3 things that reliably make baby laugh. Do them daily. The belly laugh is a major social-emotional development marker.', 'Social games and shared attention become possible around now, and they are how relationships start being two-way. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('did-mama-go-m7_9', 'social_emotional'::domain, 'm7_9'::age_band, 'Did Mama Go?', 'A short, repeatable activity that supports attachment and early social play.', 4, '3–5 min', 'None', 'Call ''Where''s Papa?'' when Papa is out of sight. Watch baby look toward the right location. Person permanence = secure attachment working.', 'Social games and shared attention become possible around now, and they are how relationships start being two-way. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('textured-surface-crawling-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Textured Surface Crawling', 'A short, repeatable activity that supports tactile discrimination.', 13, '10–15 min', 'Various surfaces', 'Let baby crawl on different surfaces: carpet, smooth floor, grass, a mat outside. Each surface is different proprioceptive input.', 'Sensory play at this stage is genuine learning, not just entertainment. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'AOTA Sensory Integration; AAP Developmental Milestones; IAP'),
  ('water-play-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Water Play', 'A playful activity that builds water play and temperature sensation.', 18, '15–20 min', 'Water, cup for pouring', 'With constant, uninterrupted supervision (never leave baby alone in water even for a moment) extend bath time to 15 min and let baby splash, pour, and explore. Water provides resistance, temperature, visual, and auditory input simultaneously.', 'Sensory play at this stage is genuine learning, not just entertainment. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'AOTA Sensory Integration; AAP Developmental Milestones; IAP'),
  ('nature-texture-explore-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Nature Texture Explore', 'A playful activity that builds tactile discrimination.', 13, '10–15 min', 'None (outdoors)', 'Outdoors: let baby touch bark, leaves, stones, soil (if safe). Natural textures are the richest sensory input available.', 'This gives your baby the range of sensations their developing nervous system needs to calibrate. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'AOTA Sensory Integration; AAP Developmental Milestones; IAP'),
  ('mouth-exploration-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Mouth Exploration', 'A hands-on activity for developing tactile discrimination.', 8, '5–10 min', 'Safe household objects of varied texture', 'At this age, mouthing is the primary sensory tool. Provide safe, clean objects of varied size and texture. Don''t interrupt unless unsafe.', 'Babies explore mainly through touch and mouth at this age, and varied input helps the sensory system develop. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'AOTA Sensory Integration; AAP Developmental Milestones; IAP'),
  ('sound-localisation-game-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Sound Localisation Game', 'A playful activity that builds auditory processing.', 7, '5–8 min', 'Any sound-making object', 'Make an interesting sound from behind baby, left, right, and above. Watch how accurately they turn toward each direction.', 'Babies explore mainly through touch and mouth at this age, and varied input helps the sensory system develop. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'AOTA Sensory Integration; AAP Developmental Milestones; IAP'),
  ('spoon-introduction-m7_9', 'social_emotional'::domain, 'm7_9'::age_band, 'Spoon Introduction', 'A playful activity that builds beginning self-feeding.', 18, '15–20 min', 'Spoon, food', 'Give baby a spoon during feeding. Messy self-feeding attempts (however unsuccessful) build fine motor and self-care simultaneously.', 'Letting your baby take part, even when it is slower, is what builds the skill. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'IAP Infant and Young Child Feeding; WHO Complementary Feeding; IAP'),
  ('cup-introduction-m7_9', 'social_emotional'::domain, 'm7_9'::age_band, 'Cup Introduction', 'A short, repeatable activity that supports drinking from a cup.', 8, '5–10 min', 'Small open cup, water', 'Offer a small open cup with a tiny amount of water. Supervised sipping: not for intake, for the skill of cup management.', 'Your baby is starting to participate in routines rather than just receive them, which is where independence begins. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'IAP Infant and Young Child Feeding; WHO Complementary Feeding; IAP'),
  ('cruising-along-furniture-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Cruising Along Furniture', 'A hands-on activity for developing cruising and first steps.', 8, '5–10 min', 'Furniture + toy', 'Place a toy at the far end of the sofa. Baby learns to step sideways while holding on: each step is a walking lesson.', 'Your baby is learning what their body can do, and the falls and wobbles are part of how that map gets built. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'WHO Motor Development Milestones; AAP Physical Activity; IAP'),
  ('steps-between-points-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Steps Between Points', 'A playful activity that builds cruising and first steps.', 8, '5–10 min', 'None', 'Sit 1–2 steps from furniture baby is holding. Open arms and call their name. Close the gap gradually as confidence grows.', 'Your baby is learning what their body can do, and the falls and wobbles are part of how that map gets built. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'WHO Motor Development Milestones; AAP Physical Activity; IAP'),
  ('standing-balance-challenge-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Standing Balance Challenge', 'A short, repeatable activity that supports pulling to stand and leg strength.', 8, '5–10 min', 'None', 'While baby stands holding furniture, catch their attention from the other side. Count the independent standing seconds each day.', 'Your baby is learning what their body can do, and the falls and wobbles are part of how that map gets built. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'WHO Motor Development Milestones; AAP Physical Activity; IAP'),
  ('stair-descent-practice-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Stair Descent Practice', 'A playful activity that builds early climbing.', 8, '5–10 min', 'Stairs', 'With you directly behind, let baby learn to descend stairs backwards (feet first). This is safer than forward and builds spatial awareness.', 'Crawling, pulling up and cruising all arrive in this window, and they arrive through practice rather than instruction. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'WHO Motor Development Milestones; AAP Physical Activity; IAP'),
  ('ball-kicking-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Ball Kicking', 'A short, repeatable activity that supports pulling to stand and leg strength.', 8, '5–10 min', 'Soft ball', 'Roll a large soft ball toward baby''s feet while they stand with support. Kicking combines balance, timing, and motor planning.', 'Your baby is learning what their body can do, and the falls and wobbles are part of how that map gets built. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'WHO Motor Development Milestones; AAP Physical Activity; IAP'),
  ('carry-while-walking-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Carry While Walking', 'A short, repeatable activity that supports cruising and first steps.', 8, '5–10 min', 'Small lightweight object', 'Ask baby to carry a lightweight object while walking (holding your hand). Dual-task walking builds automaticity.', 'Crawling, pulling up and cruising all arrive in this window, and they arrive through practice rather than instruction. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'WHO Motor Development Milestones; AAP Physical Activity; IAP'),
  ('push-along-toy-walk-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Push-Along Toy Walk', 'A short, repeatable activity that supports cruising and first steps.', 8, '5–10 min', 'Box or push-along toy', 'Give baby a push-along toy (cardboard box works) to push while walking. The resistance helps them control speed and direction.', 'Your baby is learning what their body can do, and the falls and wobbles are part of how that map gets built. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'WHO Motor Development Milestones; AAP Physical Activity; IAP'),
  ('rough-ground-walking-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Rough-Ground Walking', 'A short, repeatable activity that supports cruising and first steps.', 13, '10–15 min', 'None (outdoors)', 'Walk on grass, gravel path, or slight slope with one hand held. Variable terrain builds adaptive balance faster than smooth floors.', 'Your baby is learning what their body can do, and the falls and wobbles are part of how that map gets built. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'WHO Motor Development Milestones; AAP Physical Activity; IAP'),
  ('object-pinch-practice-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Object Pinch Practice', 'A playful activity that builds early pincer grasp.', 8, '5–10 min', 'Small safe objects', 'Offer small safe objects on a tray. A precise thumb-index pincer grip developing by 12 months is a fine motor milestone.', 'The finger and thumb grip that will later hold a spoon and a pencil begins forming in this window. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('scribble-crayon-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Scribble Crayon', 'A short, repeatable activity that supports voluntary grasp and reach.', 8, '5–10 min', 'Crayon and paper', 'Hold a crayon with baby''s hand and make marks on paper. The first deliberate mark (even if uncontrolled) is the beginning of writing.', 'Your baby is learning to let go on purpose, which is a genuinely harder skill than picking something up. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('stacking-2-3-blocks-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Stacking 2–3 Blocks', 'A short, repeatable activity that supports voluntary grasp and release.', 8, '5–10 min', 'Blocks or similar objects', 'Demonstrate stacking 2 blocks then hand one to baby. Can they place it on top? 2-block tower by 12 months = spatial milestone.', 'This is when grasping becomes deliberate rather than reflexive, and every reach and release is practice. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('post-into-container-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Post into Container', 'A short, repeatable activity that supports voluntary release.', 8, '5–10 min', 'Cardboard box and objects', 'Cut a slot in a box lid and provide objects that fit through. Posting requires visual-spatial matching: demanding for this age.', 'The finger and thumb grip that will later hold a spoon and a pencil begins forming in this window. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('turn-pages-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Turn Pages', 'A playful activity that builds page turning and finger isolation.', 7, '5–8 min', 'Board book', 'Let baby turn board book pages. Even turning multiple at once counts: the intent to turn is the milestone, not the accuracy.', 'The finger and thumb grip that will later hold a spoon and a pencil begins forming in this window. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('unscrew-lid-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Unscrew Lid', 'A playful activity that builds voluntary release.', 8, '5–10 min', 'Large lidded container', 'Offer a large-lidded container. Show loosening a lid; let them try. Rotation movements are a distinct fine motor skill.', 'This is when grasping becomes deliberate rather than reflexive, and every reach and release is practice. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('mama-dada-meaning-m10_12', 'communication'::domain, 'm10_12'::age_band, 'Mama'' ''Dada'' Meaning', 'A hands-on activity for developing babbling and early understanding.', null, 'Ongoing', 'None', 'When they say ''mama'' or ''dada'' directed at the correct person, respond warmly and immediately. First true words are emerging now.', 'Babbling is real practice for speech, and responding to it teaches your baby that sounds get answers. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('first-word-inventory-m10_12', 'communication'::domain, 'm10_12'::age_band, 'First Word Inventory', 'A playful activity that builds babbling and early understanding.', null, 'Ongoing', 'None', 'This week, note every consistent sound used to mean a specific thing. ''ba'' always for ball = a first word even if it doesn''t sound adult.', 'Understanding runs well ahead of speaking at this age, and this builds the comprehension that first words will grow from. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('expand-every-utterance-m10_12', 'communication'::domain, 'm10_12'::age_band, 'Expand Every Utterance', 'A short, repeatable activity that supports babbling and early understanding.', null, 'Ongoing', 'None', 'When baby says one word, add two: ''ba'' → ''ball! Big red ball.'' Every expansion teaches: what you said has a more complete version.', 'Babbling is real practice for speech, and responding to it teaches your baby that sounds get answers. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('bye-bye-gesture-m10_12', 'communication'::domain, 'm10_12'::age_band, 'Bye-Bye Gesture', 'A short, repeatable activity that supports pre-verbal communication (gesture).', null, 'Ongoing', 'None', 'Wave bye-bye every single time anyone leaves. First spontaneous contextual wave (not prompted) marks true gestural communication.', 'This is the window where gestures and sounds start carrying meaning, which is language beginning. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('point-name-response-m10_12', 'communication'::domain, 'm10_12'::age_band, 'Point Name Response', 'A playful activity that builds understanding first words.', null, 'Ongoing', 'None', 'Every time baby points, immediately name what they''re pointing at and comment. The point deserves a full response, every time.', 'Babbling is real practice for speech, and responding to it teaches your baby that sounds get answers. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('follow-simple-instruction-m10_12', 'communication'::domain, 'm10_12'::age_band, 'Follow Simple Instruction', 'A playful activity that builds pre-verbal communication (gesture).', 4, '3–5 min', 'None', 'Come here'' / ''Give me'' / ''Where is the ball?'' with consistent gesture. Following 1-step instructions by 12 months is a key milestone.', 'Understanding runs well ahead of speaking at this age, and this builds the comprehension that first words will grow from. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('nursery-rhymes-actions-m10_12', 'communication'::domain, 'm10_12'::age_band, 'Nursery Rhymes Actions', 'A hands-on activity for developing rhythm and pattern in language.', 8, '5–10 min', 'None', 'Sing rhymes with hand actions: ''taalee bajao'', ''Johny Johny''. Baby learns to do the actions before saying the words.', 'Babbling is real practice for speech, and responding to it teaches your baby that sounds get answers. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('3-body-parts-m10_12', 'communication'::domain, 'm10_12'::age_band, '3 Body Parts', 'A short, repeatable activity that supports understanding first words.', 4, '3–5 min', 'None', 'Staying within arm''s reach throughout, ask ''Kahaan hai naak?'' and point during bath or dressing. Recognising 2–3 body parts on command by 12 months is typical.', 'This is the window where gestures and sounds start carrying meaning, which is language beginning. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('is-it-under-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Is It Under?', 'A playful activity that builds object permanence.', 7, '5–8 min', 'Two cloths + toy', 'Hide a toy under one of two cloths while baby watches. Do they search the correct one? Searching correctly = solid object permanence.', 'This is when babies begin to understand that their actions cause things to happen, and they test it endlessly. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'Piagetian developmental framework; Harvard Center on the Developing Child; IAP'),
  ('copy-mama-s-chore-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Copy Mama''s Chore', 'A hands-on activity for developing object permanence.', 8, '5–10 min', 'Household items', 'Hand baby a cloth when you wipe a surface. Give them a spoon when you stir. They imitate because they understand the action''s purpose.', 'Your baby is discovering that things still exist when they cannot see them, which is one of the biggest ideas of the first year. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('simple-puzzle-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Simple Puzzle', 'A short, repeatable activity that supports object permanence and cause-and-effect.', 8, '5–10 min', 'Simple puzzle or homemade shape-in-box', 'A 2-piece puzzle (shape fits a hole) shows visual discrimination, spatial rotation awareness, and persistence.', 'Your baby is discovering that things still exist when they cannot see them, which is one of the biggest ideas of the first year. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('object-under-cup-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Object Under Cup', 'A playful activity that builds object permanence and cause-and-effect.', 7, '5–8 min', 'Cup and small toy', 'Show baby the toy going under one cup. Reverse the cup with the toy and ask: where did it go? Object-tracking in 3D space.', 'Thinking at this age is entirely hands-on, built by doing rather than by being shown. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('let-s-pretend-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Let''s Pretend', 'A hands-on activity for developing imitation.', 8, '5–10 min', 'Cup, spoon, or toy phone', 'Pretend to drink from an empty cup, or put a toy phone to your ear. When baby imitates: symbolic thought has arrived.', 'Thinking at this age is entirely hands-on, built by doing rather than by being shown. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'WHO Screen Time Guidelines (under 5); IAP Screen Time Guidance; IAP'),
  ('open-box-puzzle-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Open Box Puzzle', 'A playful activity that builds object permanence and cause-and-effect.', 8, '5–10 min', 'Box with lid + toy', 'Put a favourite toy in a closed (not locked) box. Watch what baby does to open it: persistence and problem-solving combined.', 'Your baby is discovering that things still exist when they cannot see them, which is one of the biggest ideas of the first year. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('affection-initiation-m10_12', 'social_emotional'::domain, 'm10_12'::age_band, 'Affection Initiation', 'A hands-on activity for developing attachment and early social play.', null, 'Ongoing', 'None', 'Note whether baby initiates affection: reaches up to be held, hugs, brings you objects. These are attachment behaviours to celebrate.', 'Your baby now knows familiar faces from unfamiliar ones, and this helps them navigate that with you close by. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('limit-testing-observation-m10_12', 'social_emotional'::domain, 'm10_12'::age_band, 'Limit Testing Observation', 'A playful activity that builds social play and reciprocity.', null, 'Ongoing', 'None', 'When baby deliberately drops something and watches your reaction: they are testing social rules. Calm, consistent responses are the lesson.', 'Social games and shared attention become possible around now, and they are how relationships start being two-way. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('empathy-seed-m10_12', 'social_emotional'::domain, 'm10_12'::age_band, 'Empathy Seed', 'A hands-on activity for developing attachment and early social play.', null, 'Ongoing', 'None', 'If someone nearby is crying or upset, narrate what you see: ''Woh reh rahi hai. Shayad dukh lag raha hai use.'' Early empathy wiring.', 'Your baby now knows familiar faces from unfamiliar ones, and this helps them navigate that with you close by. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('short-separation-practice-m10_12', 'social_emotional'::domain, 'm10_12'::age_band, 'Short Separation Practice', 'A hands-on activity for developing early separation tolerance.', 18, '15–20 min', 'None', 'Leave for a consistent 15–20 minute trip. Confident goodbye + return as promised + warmth on return = secure separation learning.', 'Social games and shared attention become possible around now, and they are how relationships start being two-way. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('alongside-another-child-m10_12', 'social_emotional'::domain, 'm10_12'::age_band, 'Alongside Another Child', 'A playful activity that builds attachment and early social play.', 18, '15–20 min', 'None', 'Arrange play near another baby. No expectation of interaction: parallel play beside another child is the correct stage right now.', 'Social games and shared attention become possible around now, and they are how relationships start being two-way. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('social-game-repetition-m10_12', 'social_emotional'::domain, 'm10_12'::age_band, 'Social Game Repetition', 'A playful activity that builds social play and reciprocity.', 8, '5–10 min', 'None', 'Repeat a social game (peek-a-boo, tickle, bounce) and stop mid-way. Watch baby signal for continuation: communication is purposeful.', 'Your baby now knows familiar faces from unfamiliar ones, and this helps them navigate that with you close by. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('sensory-bin-introduction-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Sensory Bin Introduction', 'A hands-on activity for developing tactile discrimination.', 13, '10–15 min', 'Container + dry rice or lentils', 'Fill a shallow container with dry rice or lentils. Let baby scoop, pour, and run hands through. Supervised closely.', 'Sensory play at this stage is genuine learning, not just entertainment. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'AOTA Sensory Integration; AAP Developmental Milestones; IAP'),
  ('outdoor-ground-texture-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Outdoor Ground Texture', 'A short, repeatable activity that supports tactile discrimination.', 13, '10–15 min', 'None (outdoors)', 'Let baby crawl or stand on grass, sand, or mud (if safe). The resistance and texture of outdoor ground is uniquely rich input.', 'Sensory play at this stage is genuine learning, not just entertainment. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'AOTA Sensory Integration; AAP Developmental Milestones; IAP'),
  ('music-movement-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Music Movement', 'A hands-on activity for developing auditory processing.', 8, '5–10 min', 'Music source', 'Hold baby and move to music with a clear beat. Note what genres they respond to: musical personality is forming.', 'Babies explore mainly through touch and mouth at this age, and varied input helps the sensory system develop. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'AOTA Sensory Integration; AAP Developmental Milestones; IAP'),
  ('whole-body-movement-play-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Whole-Body Movement Play', 'A hands-on activity for developing vestibular (movement) input.', 8, '5–10 min', 'Blanket', 'Roll baby gently in a blanket, lift in air briefly, spin slowly. Vestibular system thrives on varied whole-body movement.', 'Sensory play at this stage is genuine learning, not just entertainment. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'AOTA Sensory Integration; AAP Developmental Milestones; IAP'),
  ('messy-play-introduction-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Messy Play Introduction', 'A short, repeatable activity that supports tactile discrimination.', 13, '10–15 min', 'Food-based material on tray', 'Puréed food or yoghurt on a tray. Let baby touch, smear, and explore. Tactile tolerance built now prevents later sensory avoidance.', 'This gives your baby the range of sensations their developing nervous system needs to calibrate. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'AOTA Sensory Integration; AAP Developmental Milestones; IAP'),
  ('spoon-practice-self-feed-m10_12', 'social_emotional'::domain, 'm10_12'::age_band, 'Spoon Practice Self-Feed', 'A hands-on activity for developing beginning self-feeding.', 18, '15–20 min', 'Spoon + food', 'Baby-led spoon feeding: messy and slow is correct. The independence matters more than the quantity eaten.', 'Your baby is starting to participate in routines rather than just receive them, which is where independence begins. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'IAP Infant and Young Child Feeding; WHO Complementary Feeding; IAP'),
  ('shoes-socks-off-m10_12', 'social_emotional'::domain, 'm10_12'::age_band, 'Shoes Socks Off', 'A hands-on activity for developing cooperating with dressing.', 8, '5–10 min', 'Socks', 'Let baby try to remove their own socks. This develops fine motor skill and body-care independence simultaneously.', 'Early self-feeding and cooperation with dressing start now, messily and imperfectly. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'IAP Infant and Young Child Feeding; WHO Complementary Feeding; IAP'),
  ('walk-uneven-ground-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Walk Uneven Ground', 'An everyday activity that develops walking and dynamic balance.', 18, '15–20 min', 'None (outdoors)', 'Daily outdoor walking on grass, gravel, or slopes builds adaptive balance far faster than smooth indoor floors.', 'Toddlers need to move a great deal, and this gives that energy somewhere useful to go while building balance and strength. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('climbing-low-furniture-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Climbing Low Furniture', 'An everyday activity that develops climbing and stepping coordination.', 8, '5–10 min', 'Sofa cushion on floor', 'Let baby climb on and off a sofa cushion on the floor under supervision. Climbing builds shoulder, core, and spatial judgement.', 'Walking is new and still effortful, so this kind of practice is what turns a wobbly skill into an automatic one. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('squat-pick-up-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Squat Pick Up', 'A playful, repeatable activity for functional strength and carrying.', 8, '5–10 min', 'Toys on floor', 'Place toys on the floor and encourage baby to squat to retrieve them instead of bending at the waist. Squat builds hip and core strength.', 'Walking is new and still effortful, so this kind of practice is what turns a wobbly skill into an automatic one. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('kick-ball-forward-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Kick Ball Forward', 'A playful, repeatable activity for kicking and lower-body coordination.', 8, '5–10 min', 'Soft ball', 'Roll a large soft ball toward baby and encourage kicking. Timing, balance on one foot, and motor planning combine in this action.', 'Toddlers need to move a great deal, and this gives that energy somewhere useful to go while building balance and strength. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('throw-ball-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Throw Ball', 'A playful, repeatable activity for early throwing and ball skills.', 8, '5–10 min', 'Soft ball', 'Demonstrate overhead throwing and let baby try. Even wild attempts build the shoulder rotation and release control needed for throwing.', 'At this age balance is still developing, and each attempt refines it a little further. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('walk-carry-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Walk Carry', 'A playful, repeatable activity for walking and dynamic balance.', 8, '5–10 min', 'Lightweight object', 'Ask baby to carry a lightweight object from one room to another. Dual-task locomotion shows walking is becoming automatic.', 'Toddlers need to move a great deal, and this gives that energy somewhere useful to go while building balance and strength. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('dance-freely-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Dance Freely', 'A simple activity that builds rhythm and whole-body movement.', 8, '5–10 min', 'Music source', 'Put on music and dance together. Free movement to music builds coordination, rhythm, and body awareness simultaneously.', 'Toddlers need to move a great deal, and this gives that energy somewhere useful to go while building balance and strength. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('stair-up-down-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Stair Up Down', 'A playful, repeatable activity for climbing and stepping coordination.', 8, '5–10 min', 'Stairs', 'Practice going up and down stairs with one hand held. By 15 months most children can navigate with support.', 'Walking is new and still effortful, so this kind of practice is what turns a wobbly skill into an automatic one. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('crayon-mark-making-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Crayon Mark Making', 'A playful, repeatable activity for first mark-making.', 8, '5–10 min', 'Crayons and large paper', 'Large crayons on big paper. Any mark is the goal: this is the beginning of all future writing. Celebrate every mark.', 'Fine motor skill at this stage is built through play rather than practice, and this offers plenty of both. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('stacking-4-blocks-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Stacking 4+ Blocks', 'A playful, repeatable activity for stacking and controlled release.', 8, '5–10 min', 'Blocks', 'Stack 4 blocks and let baby copy. Knock down and restart. 4-block tower by 15 months is solid fine motor development.', 'This is the age where hands become genuinely useful tools, and that happens through hundreds of small attempts. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('shape-sorter-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Shape Sorter', 'A playful, repeatable activity for grasp-and-release control.', 8, '5–10 min', 'Shape sorter or homemade version', 'Start with just the circular hole: no rotation needed. Success with circle before introducing shapes that require rotation.', 'Small hands need a great deal of repetition, and this builds the strength and control that self-feeding and dressing will require. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('bead-threading-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Bead Threading', 'A simple activity that builds threading and hand-eye coordination.', 8, '5–10 min', 'Large beads/pasta + thick cord', 'Thread large beads or pasta onto a thick cord, with close, constant supervision: beads should never be left within reach when unsupervised. Requires two-hand coordination, visual targeting, and sustained attention.', 'This is the age where hands become genuinely useful tools, and that happens through hundreds of small attempts. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('fill-pour-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Fill Pour', 'An everyday activity that develops pouring and wrist control.', 8, '5–10 min', 'Two containers, water', 'With constant supervision if done during bath time, use two containers: fill one, pour into other. The control of pouring is a fine motor skill used in self-care for years.', 'Small hands need a great deal of repetition, and this builds the strength and control that self-feeding and dressing will require. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('peel-stickers-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Peel Stickers', 'A simple activity that builds pincer grasp and precision grip.', 8, '5–10 min', 'Stickers or tape on paper', 'Place large stickers on paper and let baby peel them off. Pinch-peel requires precise finger coordination.', 'Small hands need a great deal of repetition, and this builds the strength and control that self-feeding and dressing will require. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('10-word-vocabulary-m13_15', 'communication'::domain, 'm13_15'::age_band, '10+ Word Vocabulary', 'An everyday activity that develops first words and vocabulary.', null, 'Ongoing', 'None', 'Count consistent words this week including approximations. Target: 10+ words by 15 months. Each is celebrated explicitly.', 'First words appear in this window, and they appear faster in children who are talked with rather than talked at. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('two-word-combination-watch-m13_15', 'communication'::domain, 'm13_15'::age_band, 'Two-Word Combination Watch', 'A playful, repeatable activity for first words and vocabulary.', null, 'Ongoing', 'None', 'Listen for first two-word combinations: ''more doodh'', ''mama up''. These typically appear 15–18 months and mark a major leap.', 'Your toddler understands much more than they can say, and this closes that gap. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('5-body-parts-m13_15', 'communication'::domain, 'm13_15'::age_band, '5 Body Parts', 'A playful, repeatable activity for first words and vocabulary.', 4, '3–5 min', 'None', 'Extend body part naming to 5: naak, haath, paon, aankhein, kaan. Can baby point to each when named?', 'First words appear in this window, and they appear faster in children who are talked with rather than talked at. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('picture-book-naming-m13_15', 'communication'::domain, 'm13_15'::age_band, 'Picture Book Naming', 'A simple activity that builds first words and vocabulary.', 8, '5–10 min', 'Picture book', 'Point to pictures and ask ''What''s this?'' Wait. If no answer, name it and move on. No pressure: repeated exposure is what builds it.', 'Vocabulary at this age grows through repeated, everyday exchanges far more than through teaching. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('follow-2-step-instruction-m13_15', 'communication'::domain, 'm13_15'::age_band, 'Follow 2-Step Instruction', 'An everyday activity that develops following simple instructions.', 4, '3–5 min', 'Ball and box', 'Pick up the ball AND put it in the box.'' Two-step unrelated instructions mark a significant receptive language leap.', 'Vocabulary at this age grows through repeated, everyday exchanges far more than through teaching. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('pretend-telephone-call-m13_15', 'communication'::domain, 'm13_15'::age_band, 'Pretend Telephone Call', 'An everyday activity that develops two-word combinations.', 8, '5–10 min', 'Any object as phone', 'Hold a wooden spoon to your ear: ''Hello? Yeh kaun hai?'' Let baby take it. Symbolic play and communication combined.', 'Vocabulary at this age grows through repeated, everyday exchanges far more than through teaching. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'WHO Screen Time Guidelines (under 5); IAP Screen Time Guidance; IAP'),
  ('expand-add-more-m13_15', 'communication'::domain, 'm13_15'::age_band, 'Expand Add More', 'A playful, repeatable activity for first words and vocabulary.', null, 'Ongoing', 'None', 'When baby says ''ball'', say ''ball (red ball) big round ball!'' Each expansion teaches vocabulary and sentence structure simultaneously.', 'First words appear in this window, and they appear faster in children who are talked with rather than talked at. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('sing-and-fill-m13_15', 'communication'::domain, 'm13_15'::age_band, 'Sing-and-Fill', 'An everyday activity that develops first words and vocabulary.', 7, '5–8 min', 'None', 'Sing a familiar song and pause before the last word of each line. Wait for baby to fill it in vocally or with gesture.', 'Your toddler understands much more than they can say, and this closes that gap. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('simple-pretend-sequence-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Simple Pretend Sequence', 'A playful, repeatable activity for imitation and early pretend play.', 8, '5–10 min', 'Doll or soft toy, cloth', 'Baby feeds a doll, puts it to sleep, covers it with a cloth. Three-step pretend = narrative thinking beginning.', 'Toddlers learn by trying things and seeing what happens, and this gives them something worth investigating. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'AAP Safe Sleep Guidance; IAP; IAP'),
  ('find-matching-pair-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Find Matching Pair', 'A simple activity that builds object permanence and searching.', 8, '5–10 min', 'Two matching pairs of household objects', 'Give baby two identical cups and two identical spoons. Can they match the cups together and spoons together?', 'Understanding at this stage is built through direct experience, repeated many times. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('under-two-cups-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Under Two Cups', 'A simple activity that builds object permanence and searching.', 7, '5–8 min', 'Two cups + toy', 'Hide a toy under one of two cups while baby watches. Swap the cups slowly. Which cup do they check? A-not-B error is normal now.', 'This builds early problem-solving at an age when persistence is short and everything is experimental. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('sort-colour-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Sort Colour', 'An everyday activity that develops early sorting and matching.', 8, '5–10 min', 'Household objects of two colours', 'Place all red objects in one pile, all blue in another: demonstrate. Don''t expect success yet; the repeated demonstration is the teaching.', 'Toddlers learn by trying things and seeing what happens, and this gives them something worth investigating. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('early-number-concepts-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Early Number Concepts', 'A playful, repeatable activity for early sorting and matching.', 8, '5–10 min', 'Any stackable objects', 'During stacking or sorting, count aloud slowly: ''Ek, do, teen.'' One-to-one counting comprehension comes later: hearing it is the start.', 'This builds early problem-solving at an age when persistence is short and everything is experimental. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('ramp-roll-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Ramp Roll', 'An everyday activity that develops early problem-solving and matching.', 8, '5–10 min', 'Multi-action toy', 'Offer a toy with multiple actions: press this to make sound, turn that to see movement. Systematic testing of each element is science.', 'Toddlers learn by trying things and seeing what happens, and this gives them something worth investigating. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('play-beside-peer-m13_15', 'social_emotional'::domain, 'm13_15'::age_band, 'Play Beside Peer', 'A playful, repeatable activity for playing near other children.', 18, '15–20 min', 'None', 'Arrange play near another toddler. Don''t expect interaction. Parallel play is the developmentally correct stage: don''t rush sharing.', 'Toddlers have very big feelings and almost no ability to manage them, so this is about support rather than teaching. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('tantrums-as-communication-m13_15', 'social_emotional'::domain, 'm13_15'::age_band, 'Tantrums as Communication', 'A simple activity that builds early emotional regulation.', null, 'Ongoing', 'None', 'When a tantrum happens, narrate calmly: ''You''re very frustrated. You wanted that and you can''t have it. That''s hard.'' Name: don''t fix.', 'Your toddler is discovering they are a separate person with their own wants, which is why this stage is intense. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('mine-acknowledgement-m13_15', 'social_emotional'::domain, 'm13_15'::age_band, 'Mine'' Acknowledgement', 'A simple activity that builds first turn-taking.', null, 'Ongoing', 'None', 'When baby says ''mine'', acknowledge the feeling: ''Yes, that''s yours.'' Teaching ownership feelings before teaching sharing.', 'Emotional skills at this age are learned by being helped through feelings, over and over. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('comfort-object-introduction-m13_15', 'social_emotional'::domain, 'm13_15'::age_band, 'Comfort Object Introduction', 'A simple activity that builds early emotional regulation.', null, 'Ongoing', 'Preferred soft toy or cloth', 'If baby has a preferred toy or cloth, honour it. A comfort object is not a crutch: it is an autonomous self-regulation tool.', 'Emotional skills at this age are learned by being helped through feelings, over and over. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('proud-moments-response-m13_15', 'social_emotional'::domain, 'm13_15'::age_band, 'Proud Moments Response', 'An everyday activity that develops emotional expression and early social skills.', null, 'Ongoing', 'None', 'When baby achieves something, your response matters. Specific warm praise: ''You put all the blocks in! You worked hard at that.''', 'Toddlers have very big feelings and almost no ability to manage them, so this is about support rather than teaching. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('independence-play-m13_15', 'social_emotional'::domain, 'm13_15'::age_band, 'Independence Play', 'An everyday activity that develops emotional expression and early social skills.', 8, '5–10 min', 'Safe toy collection', 'Create a safe floor space and let baby play alone for 5–10 minutes without intervention. Independent play is a skill to build.', 'Emotional skills at this age are learned by being helped through feelings, over and over. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('messy-sensory-play-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Messy Sensory Play', 'A playful, repeatable activity for tactile exploration.', 13, '10–15 min', 'Food material on tray', 'Cooked spaghetti, wet sand, or yoghurt on a tray. Sensory tolerance for unfamiliar textures is built through repeated low-pressure exposure.', 'Messy, tactile play at this age builds tolerance that makes eating and dressing easier too. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('nature-walk-collect-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Nature Walk Collect', 'A simple activity that builds natural sensory environments.', 25, '20–30 min', 'Bag for collecting', 'Walk outdoors and collect leaves, stones, sticks (safe). Back home, handle and sort them. Natural materials are rich sensory input.', 'This supports the sensory processing that underlies calm, settled behaviour. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP')
